import{_ as a,o as i,c as t,a2 as e}from"./chunks/framework.CQdiwDJy.js";const c=JSON.parse('{"title":"Installation & quick start","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/getting-started.md","filePath":"en/guide/getting-started.md","lastUpdated":1788601681000}'),n={name:"en/guide/getting-started.md"};function l(r,s,h,p,d,o){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="installation-quick-start" tabindex="-1">Installation &amp; quick start <a class="header-anchor" href="#installation-quick-start" aria-label="Permalink to &quot;Installation &amp; quick start&quot;">​</a></h1><p>Tau is an AI assistant that lives in your terminal: you state an intent in natural language, it produces a structured plan, the plan passes a deterministic safety review and waits for your approval before anything runs. It is not &quot;AI typing commands&quot; — it is &quot;AI proposes, rules review, you decide&quot;.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>Tau is a pnpm monorepo; run or build from source:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Z-Yun-H/Tau.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tau</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># pipe-friendly mode (CLI)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;*.ts&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># multi-round agent mode</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;organize all .bak files under src into a cleanup dir&quot;</span></span></code></pre></div><h2 id="three-front-doors" tabindex="-1">Three front doors <a class="header-anchor" href="#three-front-doors" aria-label="Permalink to &quot;Three front doors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Command</th><th>Best for</th></tr></thead><tbody><tr><td>CLI</td><td><code>tau ask &quot;&lt;intent&gt;&quot;</code></td><td>pipes, scripts, one-shot answers</td></tr><tr><td>TUI</td><td><code>tau tui</code></td><td>full-screen keyboard flow</td></tr><tr><td>WebUI</td><td><code>tau web</code></td><td>thinking panels and tool cards in the browser</td></tr></tbody></table><p>All three share the same engine and the same safety gate — the review verdict you see in the WebUI is exactly the one the CLI prints.</p><h2 id="configure-a-provider" tabindex="-1">Configure a provider <a class="header-anchor" href="#configure-a-provider" aria-label="Permalink to &quot;Configure a provider&quot;">​</a></h2><p>Tau needs at least one AI provider to plan:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tau</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> providers.deepseek.apiKey</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;sk-...&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tau</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deepseek</span></span></code></pre></div><p>No network yet? The built-in <code>mock</code> provider emits deterministic plans and reasoning traces — the entire pipeline (including the WebUI streaming thinking panel) demos offline.</p><h2 id="the-safety-model-in-60-seconds" tabindex="-1">The safety model in 60 seconds <a class="header-anchor" href="#the-safety-model-in-60-seconds" aria-label="Permalink to &quot;The safety model in 60 seconds&quot;">​</a></h2><p>Three things happen before anything executes: <strong>plan</strong> (the provider emits a strict-JSON step list) → <strong>review</strong> (deterministic code, never AI self-grading) → <strong>confirm</strong> (high-risk steps demand explicit approval). <code>runPlan()</code> is the only execution channel; there is no bypass. See the <a href="/Tau/en/reference/safety.html">safety model</a>.</p>`,14)])])}const g=a(n,[["render",l]]);export{c as __pageData,g as default};
